### Exercise each setting with the control's real step size

**Severity:** `medium`

The slider has `SmallChange="100"`, but `QuickSetValue` sends one arrow press per integer; requesting 800 from 1200 therefore sends 400 presses and clamps at the minimum. The existing checkbox checks also leave the default-on right button unchanged and never exercise the left binding. Drive the slider from Home in 100-ms steps, toggle every checkbox away from its default, and assert the NumberBox value after editing.

```suggestion
            mmbLock.SetCheck(true);
            Assert.IsTrue(mmbLock.IsChecked);
            mmbLock.SetCheck(false);
            Assert.IsFalse(mmbLock.IsChecked);

            rmbLock.SetCheck(false);
            Assert.IsFalse(rmbLock.IsChecked);
            rmbLock.SetCheck(true);
            Assert.IsTrue(rmbLock.IsChecked);

            lmbLock.SetCheck(true);
            Assert.IsTrue(lmbLock.IsChecked);
            lmbLock.SetCheck(false);
            Assert.IsFalse(lmbLock.IsChecked);

            // [Test Case] Hold duration snaps to 100 ms steps across the 200-2200 ms range.
            var holdDuration = foundCustom.Find<Slider>(By.AccessibilityId(MouseUtilsSettings.AccessibilityIds.MouseButtonLockHoldDuration));
            Assert.IsNotNull(holdDuration);

            holdDuration.Click();
            holdDuration.SendKeys(Key.Home);
            for (int i = 0; i < 6; i++)
            {
                holdDuration.SendKeys(Key.Right);
            }

            Assert.AreEqual(800, holdDuration.GetValue());

            for (int i = 0; i < 4; i++)
            {
                holdDuration.SendKeys(Key.Right);
            }

            Assert.AreEqual(1200, holdDuration.GetValue());

            // [Test Case] Drag threshold accepts a value. The NumberBox surfaces to automation as an edit control.
            var moveCancelPixels = foundCustom.Find<TextBox>(By.AccessibilityId(MouseUtilsSettings.AccessibilityIds.MouseButtonLockMoveCancelPixels));
            Assert.IsNotNull(moveCancelPixels);
            moveCancelPixels.SetText("12");
            Assert.AreEqual("12", moveCancelPixels.Text);
```
